    static string Tenant(HttpContext c) => c.Items["tenant"]!.ToString()!; static PrincipalContext Principal(HttpContext c) => (PrincipalContext)c.Items["principal"]!; static string Actor(HttpContext c) => Principal(c).Subject; static IReadOnlySet<string> Permissions(HttpContext c) => (IReadOnlySet<string>)c.Items["permissions"]!; static IResult Ok(HttpContext c, object value) => Results.Ok(new ApiEnvelope<object>(value, new(c.TraceIdentifier, "1.0"))); static IResult Problem(HttpContext c, string code, string detail) => Results.Problem(statusCode: 400, title: code, detail: detail, extensions: new Dictionary<string, object?> { { "code", code }, { "traceId", c.TraceIdentifier } });
    public static void Map(WebApplication app)
    {
        app.MapPost("/api/v1/live-response/sessions", Create).RequirePermission("live:open"); app.MapGet("/api/v1/live-response/sessions", List).RequirePermission("live:read"); app.MapGet("/api/v1/live-response/sessions/{id:guid}", Get).RequirePermission("live:read"); app.MapGet("/api/v1/live-response/sessions/{id:guid}/history", History).RequirePermission("live:read"); app.MapPost("/api/v1/live-response/sessions/{id:guid}:approve", Approve).RequirePermission("live:approve:elevated"); app.MapPost("/api/v1/live-response/sessions/{id:guid}:reject", Reject).RequirePermission("live:approve:elevated"); app.MapPost("/api/v1/live-response/sessions/{id:guid}:presence", Presence).RequirePermission("live:read"); app.MapPost("/api/v1/live-response/sessions/{id:guid}:close", Close).RequirePermission("live:close:own");
        app.MapPost("/api/v1/live-response/sessions/{id:guid}/commands", SubmitDispatch).RequirePermission("live:execute:safe"); app.MapGet("/api/v1/live-response/sessions/{session:guid}/commands/{command:guid}", Command).RequirePermission("live:read"); app.MapGet("/api/v1/live-response/sessions/{session:guid}/commands/{command:guid}/output", Output).RequirePermission("live:read"); app.MapGet("/api/v1/live-response/sessions/{session:guid}/commands/{command:guid}/result", Result).RequirePermission("live:read"); app.MapPost("/api/v1/live-response/sessions/{session:guid}/commands/{command:guid}:cancel", Cancel).RequirePermission("live:cancel");
        app.MapGet("/api/v1/live-response/sessions/{id:guid}/transcript", Transcript).RequirePermission("live:transcript:read"); app.MapPost("/api/v1/live-response/sessions/{id:guid}/transcript:export", ExportTranscript).RequirePermission("live:transcript:export"); app.MapGet("/api/v1/live-response/artifacts/{artifact:guid}", ArtifactMetadata).RequirePermission("live:file:download"); app.MapGet("/api/v1/live-response/artifacts/{artifact:guid}/content", ArtifactContent).RequirePermission("live:file:download"); app.MapPost("/api/v1/live-response/artifacts/{artifact:guid}:url", ArtifactUrl).RequirePermission("live:file:download"); app.MapGet("/api/v1/live-response/artifacts/{artifact:guid}/download", SignedArtifact); app.MapGet("/api/v1/live-response/health", Health).RequirePermission("live:read");
        app.MapGet("/agent/v1/live-response/sessions", Assignments).RequirePermission("agent:heartbeat"); app.MapPost("/agent/v1/live-response/sessions/{id:guid}:transition", AgentSession).RequirePermission("agent:heartbeat"); app.MapGet("/agent/v1/live-response/commands", Commands).RequirePermission("agent:heartbeat"); app.MapPost("/agent/v1/live-response/commands/{id:guid}:transition", AgentCommand).RequirePermission("agent:heartbeat"); app.MapPost("/agent/v1/live-response/commands/{id:guid}/chunks", AgentChunk).RequirePermission("agent:heartbeat"); app.MapPost("/agent/v1/live-response/commands/{id:guid}:complete", AgentComplete).RequirePermission("agent:heartbeat"); app.MapGet("/agent/v1/live-response/cancellations", AgentCancellations).RequirePermission("agent:heartbeat");
