    static async Task<IResult> Create(LiveSessionRequest input, HttpContext c, ILiveResponseRepository r, IResponseActionRepository endpoints, IAlertIncidentRepository triage, CancellationToken ct) { var tenant = Tenant(c); var permissions = Permissions(c); foreach (var capability in input.Capabilities) { var required = capability switch { "builtin" => "live:execute:safe", "cmd" => "live:execute:cmd", "powershell" => "live:execute:powershell", "file-download" => "live:file:download", "file-upload" => "live:file:upload", _ => "" }; if (!permissions.Contains("platform:admin") && !permissions.Contains(required)) return Results.Forbid(); } var target = await endpoints.ResolveTargetAsync(tenant, input.EndpointId, ct); if (target is null) return Results.NotFound(); if (target.Status is EndpointStatus.Disabled or EndpointStatus.Revoked) return Problem(c, "LIVE_ENDPOINT_DISABLED", "Disabled or revoked endpoint cannot open Live Response."); if (target.Status == EndpointStatus.Offline) return Problem(c, "LIVE_ENDPOINT_OFFLINE", "The selected endpoint installation is offline. Choose the current online installation before opening Live Response."); if (!string.Equals(target.Platform, "windows", StringComparison.OrdinalIgnoreCase)) return Problem(c, "LIVE_PLATFORM_UNSUPPORTED", "Sprint 17 Live Response is qualified only for Windows endpoints."); if (input.SourceAlertId is { } alert && await triage.GetAlertAsync(tenant, alert, ct) is null) return Problem(c, "LIVE_ALERT_CONTEXT", "Source alert is unavailable in this tenant."); if (input.SourceIncidentId is { } incident && await triage.GetIncidentAsync(tenant, incident, ct) is null) return Problem(c, "LIVE_INCIDENT_CONTEXT", "Source incident is unavailable in this tenant."); var value = await r.CreateAsync(new(tenant, target.EndpointId, target.AgentId, target.AgentInstallationId, target.Platform, target.AgentVersion, Actor(c), permissions.ToArray(), input), ct); return Results.Created($"/api/v1/live-response/sessions/{value.SessionId:D}", new ApiEnvelope<object>(value, new(c.TraceIdentifier, "1.0"))); }
    static async Task<IResult> List(HttpContext c, ILiveResponseRepository r, CancellationToken ct) => Ok(c, await r.ListAsync(Tenant(c), Guid.TryParse(c.Request.Query["endpointId"], out var endpoint) ? endpoint : null, ct)); static async Task<IResult> Get(Guid id, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => await r.GetAsync(Tenant(c), id, ct) is { } x ? Ok(c, x) : Results.NotFound(); static async Task<IResult> History(Guid id, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => await r.GetAsync(Tenant(c), id, ct) is { } x ? Ok(c, x.Commands) : Results.NotFound(); static async Task<IResult> Approve(Guid id, LiveApprovalRequest input, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => Ok(c, await r.ApproveAsync(Tenant(c), id, Actor(c), input, ct)); static async Task<IResult> Reject(Guid id, ReasonRequest input, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => Ok(c, await r.RejectAsync(Tenant(c), id, Actor(c), input.Reason, ct)); static async Task<IResult> Presence(Guid id, LivePresenceRequest input, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => Ok(c, await r.PresenceAsync(Tenant(c), id, Actor(c), input, ct)); static async Task<IResult> Close(Guid id, LiveCloseRequest input, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => Ok(c, await r.CloseAsync(Tenant(c), id, Actor(c), input, Permissions(c).Contains("live:close:any"), ct));
    static async Task<IResult> SubmitDispatch(Guid id, LiveCommandRequest input, HttpContext c, ILiveResponseRepository r, IObjectStorage storage, IProcessTelemetryRepository processes, IFileTelemetryRepository files, IPersistenceTelemetryRepository persistence, IResponseActionRepository actions, IAlertIncidentRepository triage, ToolPackageStore tools, CancellationToken ct)
    {
        if (input.CommandType == LiveCommandType.BuiltIn)
        {
            var tokens = LiveResponseSafety.Tokenize(input.Input);
            if (tokens.Length == 0) return Problem(c, "LIVE_BUILTIN_EMPTY", "A built-in command is required.");
            if (tokens[0].Equals("stage-tool", StringComparison.OrdinalIgnoreCase) || tokens[0].Equals("remove-tool", StringComparison.OrdinalIgnoreCase))
            {
                var session = await r.GetAsync(Tenant(c), id, ct); if (session is null) return Results.NotFound();
                if (session.State != LiveSessionState.Active || session.AnalystId != Actor(c) ||
                    !session.Capabilities.Contains("file-upload", StringComparer.Ordinal) ||
                    !Permissions(c).Contains("platform:admin") && !Permissions(c).Contains("live:file:upload")) return Results.Forbid();
                if (tokens[0].Equals("stage-tool", StringComparison.OrdinalIgnoreCase) &&
                    (!Guid.TryParse(tokens[1], out var packageId) || await tools.GetAsync(Tenant(c), packageId, ct) is not { State: "approved" }))
                    return Problem(c, "LIVE_TOOL_PACKAGE", "Tool package is unavailable or revoked.");
            }
        }
        if (input.CommandType == LiveCommandType.BuiltIn && LiveResponseSafety.TryStructuredForensicAction(input.Input, out var operation, out var argument))
        {
            var session = await r.GetAsync(Tenant(c), id, ct); if (session is null) return Results.NotFound();
            if (session.State != LiveSessionState.Active || session.AnalystId != Actor(c)) return Problem(c, "LIVE_SESSION_NOT_ACTIVE", "Owned active session is required.");
            var permission = operation switch { "collect-file" => "forensics:request:file", "collect-eventlog" => "forensics:request:eventlog", "collect-registry" => "forensics:request:registry", "cancel-collection" => "forensics:cancel", "collection-status" => "forensics:read", _ => "forensics:request:quick" };
            if (!Permissions(c).Contains("platform:admin") && !Permissions(c).Contains(permission)) return Results.Forbid();
            await r.AuditAsync(Tenant(c), id, null, Actor(c), "live.structured-forensic-collection.requested", operation, LiveResponseSafety.Hash(input.Input), new Dictionary<string, string?> { ["operation"] = operation, ["argument"] = argument.Length == 0 ? null : "exact-structured-identifier" }, ct);
            return await ForensicCollectionRoutes.FromLive(operation, argument, session, input.TimeoutSeconds, c, files, actions, triage, ct);
        }
        if (input.CommandType == LiveCommandType.BuiltIn && LiveResponseSafety.StructuredForensicBuiltIns.Any(x => input.Input.StartsWith(x, StringComparison.OrdinalIgnoreCase))) return Problem(c, "LIVE_FORENSIC_INVALID", "Structured collection requires the exact bounded profile argument; paths, wildcards, and recursive sweeps are forbidden.");
        return await Submit(id, input, c, r, storage, processes, files, persistence, actions, triage, ct);
    }
    static async Task<IResult> Submit(Guid id, LiveCommandRequest input, HttpContext c, ILiveResponseRepository r, IObjectStorage storage, IProcessTelemetryRepository processes, IFileTelemetryRepository files, IPersistenceTelemetryRepository persistence, IResponseActionRepository actions, IAlertIncidentRepository triage, CancellationToken ct) { var required = input.CommandType switch { LiveCommandType.Cmd => "live:execute:cmd", LiveCommandType.PowerShell => "live:execute:powershell", LiveCommandType.Upload => "live:file:upload", _ => "live:execute:safe" }; if (!Permissions(c).Contains("platform:admin") && !Permissions(c).Contains(required)) return Results.Forbid(); if (input.CommandType == LiveCommandType.BuiltIn && LiveResponseSafety.TryStructuredProcessAction(input.Input, out var processAction, out var entity)) { var session = await r.GetAsync(Tenant(c), id, ct); if (session is null) return Results.NotFound(); if (session.State != LiveSessionState.Active || session.AnalystId != Actor(c)) return Problem(c, "LIVE_SESSION_NOT_ACTIVE", "Owned active session is required."); var processPermission = processAction switch { "process.terminate" => "process-response:terminate", "process.suspend" => "process-response:suspend", "process.resume" => "process-response:resume", _ => "process-response:read" }; if (!Permissions(c).Contains("platform:admin") && !Permissions(c).Contains(processPermission)) return Results.Forbid(); await r.AuditAsync(Tenant(c), id, null, Actor(c), "live.structured-process-response.requested", processAction, LiveResponseSafety.Hash(input.Input), new Dictionary<string, string?> { ["processEntityId"] = entity, ["structuredAction"] = processAction }, ct); return await ProcessResponseRoutes.CreateSingle(processAction, session.EndpointId, entity, new($"Live Response structured action from session {id:D}", input.TimeoutSeconds + 60, session.SourceAlertId, session.SourceIncidentId, entity), c, processes, actions, triage, ct); } if (input.CommandType == LiveCommandType.BuiltIn && LiveResponseSafety.TryStructuredFileAction(input.Input, out var fileAction, out var fileIdentity)) { var session = await r.GetAsync(Tenant(c), id, ct); if (session is null) return Results.NotFound(); if (session.State != LiveSessionState.Active || session.AnalystId != Actor(c)) return Problem(c, "LIVE_SESSION_NOT_ACTIVE", "Owned active session is required."); var permission = fileAction switch { "file.quarantine" => "file-response:quarantine", "file.restore" => "file-response:restore", "file.delete" => "file-response:delete", _ => "file-response:read" }; if (!Permissions(c).Contains("platform:admin") && !Permissions(c).Contains(permission)) return Results.Forbid(); await r.AuditAsync(Tenant(c), id, null, Actor(c), "live.structured-file-response.requested", fileAction, LiveResponseSafety.Hash(input.Input), new Dictionary<string, string?> { ["fileOrQuarantineIdentity"] = fileIdentity, ["structuredAction"] = fileAction }, ct); var reason = $"Live Response structured action from session {id:D}"; if (fileAction is "file.quarantine" or "file.delete") return await FileResponseRoutes.CreateFile(fileAction, session.EndpointId, fileIdentity, new(reason, input.TimeoutSeconds + 60, session.SourceAlertId, session.SourceIncidentId, fileIdentity), c, files, actions, triage, ct); var quarantineId = Guid.Parse(fileIdentity); if (fileAction == "file.restore") return await FileResponseRoutes.Restore(quarantineId, new(reason, input.TimeoutSeconds + 60, session.SourceAlertId, session.SourceIncidentId, session.SourceEntityId), c, actions, triage, ct); return await FileResponseRoutes.CreateRecordAction(quarantineId, fileAction, reason, c, actions, ct); } if (input.CommandType == LiveCommandType.BuiltIn && LiveResponseSafety.TryStructuredPersistenceAction(input.Input, out var persistenceAction, out var persistenceIdentity)) { var session = await r.GetAsync(Tenant(c), id, ct); if (session is null) return Results.NotFound(); if (session.State != LiveSessionState.Active || session.AnalystId != Actor(c)) return Problem(c, "LIVE_SESSION_NOT_ACTIVE", "Owned active session is required."); var permission = persistenceAction switch { "persistence.remediation_status" => "persistence-response:read", "service.stop" => "persistence-response:service:stop", "service.disable" => "persistence-response:service:disable", "scheduled_task.disable" => "persistence-response:task:disable", "persistence.restore" => "persistence-response:restore", _ => "persistence-response:request" }; if (!Permissions(c).Contains("platform:admin") && !Permissions(c).Contains(permission)) return Results.Forbid(); await r.AuditAsync(Tenant(c), id, null, Actor(c), "live.structured-persistence-response.requested", persistenceAction, LiveResponseSafety.Hash(input.Input), new Dictionary<string, string?> { ["persistenceOrBackupIdentity"] = persistenceIdentity, ["structuredAction"] = persistenceAction }, ct); var reason = $"Live Response structured action from session {id:D}"; if (persistenceAction == "persistence.remediation_status") return await PersistenceResponseRoutes.PreviewSingle(session.EndpointId, persistenceIdentity, c, persistence, actions, ct); if (persistenceAction == "persistence.restore") return await PersistenceResponseRoutes.Restore(Guid.Parse(persistenceIdentity), new(reason, input.TimeoutSeconds + 60, session.SourceAlertId, session.SourceIncidentId, session.SourceEntityId), c, actions, triage, ct); return await PersistenceResponseRoutes.CreateSingle(persistenceAction, session.EndpointId, persistenceIdentity, new(persistenceAction, reason, input.TimeoutSeconds + 60, session.SourceAlertId, session.SourceIncidentId, persistenceIdentity), c, persistence, actions, triage, ct); } if (input.CommandType == LiveCommandType.BuiltIn && LiveResponseSafety.StructuredProcessBuiltIns.Concat(LiveResponseSafety.StructuredFileBuiltIns).Concat(LiveResponseSafety.StructuredPersistenceBuiltIns).Any(x => input.Input.StartsWith(x, StringComparison.OrdinalIgnoreCase))) return Problem(c, "LIVE_STRUCTURED_RESPONSE_INVALID", "Structured response requires one exact canonical entity or quarantine identity; path and PID shortcuts are forbidden."); if (input.CommandType == LiveCommandType.Upload) { FileLiveResponseRepository.ValidateUpload(input); var encoded = input.UploadContentBase64!; var hash = input.UploadSha256!; var bytes = Convert.FromBase64String(encoded); var staging = InvestigationSafety.StableId("live-upload-staging", Tenant(c), id.ToString("D"), hash); await using var stream = new MemoryStream(bytes, false); await storage.UploadAsync(Tenant(c), staging.ToString("D"), stream, "application/octet-stream", hash, ct); } var value = await r.SubmitAsync(Tenant(c), id, Actor(c), input, ct); return Results.Created($"/api/v1/live-response/sessions/{id:D}/commands/{value.CommandId:D}", new ApiEnvelope<object>(value, new(c.TraceIdentifier, "1.0"))); }
    static async Task<(LiveSessionRecord Session, LiveCommandRecord Command)?> Find(string tenant, Guid session, Guid command, ILiveResponseRepository r, CancellationToken ct) { var s = await r.GetAsync(tenant, session, ct); var cmd = s?.Commands.FirstOrDefault(x => x.CommandId == command); return s is null || cmd is null ? null : (s, cmd); }
    static async Task<IResult> Command(Guid session, Guid command, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => await Find(Tenant(c), session, command, r, ct) is { } x ? Ok(c, x.Command) : Results.NotFound(); static async Task<IResult> Output(Guid session, Guid command, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => await Find(Tenant(c), session, command, r, ct) is { } x ? Ok(c, x.Command.Output) : Results.NotFound(); static async Task<IResult> Result(Guid session, Guid command, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => await Find(Tenant(c), session, command, r, ct) is { Command.Result: { } result } ? Ok(c, result) : Results.NotFound(); static async Task<IResult> Cancel(Guid session, Guid command, ReasonRequest input, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => Ok(c, await r.CancelAsync(Tenant(c), session, command, Actor(c), input.Reason, ct));
    static async Task<IResult> Transcript(Guid id, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => await r.GetAsync(Tenant(c), id, ct) is { } s ? Ok(c, new { s.Transcript, s.TranscriptHash, verified = LiveResponseSafety.TranscriptHash(s.Transcript) == s.TranscriptHash }) : Results.NotFound(); static async Task<IResult> ExportTranscript(Guid id, HttpContext c, ILiveResponseRepository r, IObjectStorage storage, CancellationToken ct) { var s = await r.GetAsync(Tenant(c), id, ct); if (s is null) return Results.NotFound(); var bytes = Encoding.UTF8.GetBytes(string.Join('\n', s.Transcript.Select(x => JsonSerializer.Serialize(x))) + '\n'); var hash = Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(); var objectId = InvestigationSafety.StableId("live-transcript-export", s.SessionId.ToString("D"), s.TranscriptHash); await using var stream = new MemoryStream(bytes, false); await storage.UploadAsync(s.TenantId, objectId.ToString("D"), stream, "application/x-ndjson", hash, ct); await r.AuditAsync(s.TenantId, s.SessionId, null, Actor(c), "live.transcript.exported", objectId.ToString("D"), hash, new Dictionary<string, string?> { { "records", s.Transcript.Length.ToString(System.Globalization.CultureInfo.InvariantCulture) } }, ct); return Ok(c, new { objectId, records = s.Transcript.Length, sha256 = hash, s.TranscriptHash }); }
    static async Task<(LiveSessionRecord, LiveArtifact)?> FindArtifact(string tenant, Guid id, ILiveResponseRepository r, CancellationToken ct) { foreach (var s in await r.ListAsync(tenant, null, ct)) foreach (var command in s.Commands) if (command.Result?.Artifacts.FirstOrDefault(x => x.ArtifactId == id && x.ExpiresAt > DateTimeOffset.UtcNow) is { } a) return (s, a); return null; }
    static async Task<IResult> ArtifactMetadata(Guid artifact, HttpContext c, ILiveResponseRepository r, CancellationToken ct) => await FindArtifact(Tenant(c), artifact, r, ct) is { } x ? Ok(c, x.Item2) : Results.NotFound(); static async Task<IResult> ArtifactContent(Guid artifact, HttpContext c, ILiveResponseRepository r, IObjectStorage storage, CancellationToken ct) { if (await FindArtifact(Tenant(c), artifact, r, ct) is not { } x) return Results.NotFound(); await r.AuditAsync(Tenant(c), x.Item1.SessionId, x.Item2.CommandId, Actor(c), "live.artifact.downloaded", artifact.ToString("D"), x.Item2.Sha256, new Dictionary<string, string?>(), ct); return Results.Stream(await storage.DownloadAsync(Tenant(c), x.Item2.ObjectId, ct), x.Item2.MediaType); }
    static async Task<IResult> ArtifactUrl(Guid artifact, ArtifactUrlRequest input, HttpContext c, ILiveResponseRepository r, PlatformOptions o, CancellationToken ct) { if (await FindArtifact(Tenant(c), artifact, r, ct) is null) return Results.NotFound(); var expires = DateTimeOffset.UtcNow.AddSeconds(Math.Clamp(input.ExpiresInSeconds, 5, 300)); return Ok(c, new { url = $"{c.Request.Scheme}://{c.Request.Host}/api/v1/live-response/artifacts/{artifact:D}/download?token={Uri.EscapeDataString(FileExportDownloadToken.Create(Tenant(c), artifact, expires, o.JwtSigningKey))}", expiresAt = expires }); }
    static async Task<IResult> SignedArtifact(Guid artifact, string token, ILiveResponseRepository r, IObjectStorage storage, PlatformOptions o, CancellationToken ct) { if (!FileExportDownloadToken.TryValidate(token, o.JwtSigningKey, out var tenant, out var target) || target != artifact || await FindArtifact(tenant, artifact, r, ct) is not { } x) return Results.NotFound(); await r.AuditAsync(tenant, x.Item1.SessionId, x.Item2.CommandId, "signed-url", "live.artifact.downloaded", artifact.ToString("D"), x.Item2.Sha256, new Dictionary<string, string?>(), ct); return Results.Stream(await storage.DownloadAsync(tenant, x.Item2.ObjectId, ct), x.Item2.MediaType); }
    static async Task<IResult> Health(HttpContext c, ILiveResponseRepository r, CancellationToken ct) => Ok(c, await r.HealthAsync(Tenant(c), ct));
    static bool Agent(HttpContext c, out PrincipalContext p, out Guid endpoint, out Guid agent) { endpoint = Guid.Empty; agent = Guid.Empty; p = (PrincipalContext?)c.Items["principal"] ?? new("", "", new HashSet<string>(), ""); var ids = p.Subject.Split(':'); return p.Type == "agent" && ids.Length == 2 && Guid.TryParse(ids[0], out endpoint) && Guid.TryParse(ids[1], out agent); }
    static string? Installation(HttpContext c) => c.Request.Headers["X-Agent-Installation-Id"].FirstOrDefault();
    static async Task<IResult> Assignments(HttpContext c, ILiveResponseRepository r, CertificateAuthority ca, CancellationToken ct) { if (!Agent(c, out var p, out var endpoint, out var agent) || Installation(c) is not { } installation) return Results.Unauthorized(); return Ok(c, (await r.AssignAsync(p.TenantId, endpoint, agent, installation, ct)).Select(ca.SignLiveSession).ToArray()); }
    static async Task<IResult> AgentSession(Guid id, LiveAgentSessionTransition input, HttpContext c, ILiveResponseRepository r, CancellationToken ct) { if (id != input.SessionId || !Agent(c, out var p, out var endpoint, out var agent)) return Results.Unauthorized(); return Ok(c, await r.AgentSessionAsync(p.TenantId, endpoint, agent, input, ct)); }
    static async Task<IResult> Commands(HttpContext c, ILiveResponseRepository r, CertificateAuthority ca, CancellationToken ct) { if (!Agent(c, out var p, out var endpoint, out var agent) || Installation(c) is not { } installation) return Results.Unauthorized(); return Ok(c, (await r.DeliverAsync(p.TenantId, endpoint, agent, installation, ct)).Select(ca.SignLiveCommand).ToArray()); }
    static async Task<IResult> AgentCommand(Guid id, LiveAgentCommandTransition input, HttpContext c, ILiveResponseRepository r, CancellationToken ct) { if (id != input.CommandId || !Agent(c, out var p, out var endpoint, out var agent)) return Results.Unauthorized(); return Ok(c, await r.AgentCommandAsync(p.TenantId, endpoint, agent, input, ct)); }
    static async Task<IResult> AgentChunk(Guid id, LiveOutputChunk input, HttpContext c, ILiveResponseRepository r, CancellationToken ct) { if (id != input.CommandId || !Agent(c, out var p, out var endpoint, out var agent)) return Results.Unauthorized(); return Ok(c, await r.AppendChunkAsync(p.TenantId, endpoint, agent, id, input, ct)); }
    static async Task<IResult> AgentComplete(Guid id, LiveAgentCompletion input, HttpContext c,
        ILiveResponseRepository r, IObjectStorage storage, ArtifactTransferStore transfers, CancellationToken ct)
    {
        if (id != input.CommandId || !Agent(c, out var p, out var endpoint, out var agent) || Installation(c) is not { } installation) return Results.Unauthorized();
        var artifacts = new List<LiveArtifact>();
        foreach (var upload in input.Artifacts)
        {
            string objectId; long size;
            if (upload.TransferId is { } transferId)
            {
                var transfer = await transfers.AgentStatusAsync(p.TenantId, endpoint, agent, installation, transferId, ct);
                if (transfer.State != ArtifactTransferState.Completed || transfer.OwnerType != "live-response" ||
                    transfer.OwnerId != id || transfer.ArtifactId != upload.ArtifactId || transfer.Size != upload.Size ||
                    !string.Equals(transfer.Sha256, upload.Sha256, StringComparison.OrdinalIgnoreCase) || transfer.ObjectId is null)
                    return Problem(c, "LIVE_ARTIFACT_TRANSFER_BINDING", "Completed artifact transfer is not bound to this command result.");
                objectId = transfer.ObjectId; size = transfer.Size;
            }
            else
            {
                byte[] bytes; try { bytes = Convert.FromBase64String(upload.ContentBase64 ?? ""); }
                catch (FormatException) { return Problem(c, "LIVE_ARTIFACT_ENCODING", "Artifact encoding is invalid."); }
                if (bytes.Length > LiveResponseSafety.HardLimits.MaximumTransferBytes ||
                    !string.Equals(Convert.ToHexString(SHA256.HashData(bytes)), upload.Sha256, StringComparison.OrdinalIgnoreCase))
                    return Problem(c, "LIVE_ARTIFACT_INTEGRITY", "Legacy artifact size or hash is invalid.");
                objectId = Guid.NewGuid().ToString("D"); size = bytes.LongLength;
                await using var stream = new MemoryStream(bytes, false);
                await storage.UploadAsync(p.TenantId, objectId, stream, upload.MediaType, upload.Sha256, ct);
            }
            var manifestId = InvestigationSafety.StableId("live-artifact-manifest", p.TenantId, input.SessionId.ToString("D"), id.ToString("D"), upload.ArtifactId.ToString("D"));
            var manifest = JsonSerializer.SerializeToUtf8Bytes(new { schemaVersion = "live-response-artifact-manifest.v2", tenantBinding = p.TenantId, input.SessionId, commandId = id, upload.ArtifactId, objectId, upload.Name, bytes = size, upload.Sha256, upload.NativeIdentity, upload.Consistent, transferId = upload.TransferId, transport = upload.TransferId is null ? "legacy-base64" : ArtifactTransferSafety.SchemaVersion, createdAt = DateTimeOffset.UtcNow });
            await using (var stream = new MemoryStream(manifest, false)) await storage.UploadAsync(p.TenantId, manifestId.ToString("D"), stream, "application/json", Convert.ToHexString(SHA256.HashData(manifest)).ToLowerInvariant(), ct);
            artifacts.Add(new(upload.ArtifactId, id, upload.Name, upload.MediaType, size, upload.Sha256, objectId,
                manifestId, upload.NativeIdentity, upload.Consistent, DateTimeOffset.UtcNow, DateTimeOffset.UtcNow.AddDays(7)));
        }
        return Ok(c, await r.CompleteAsync(p.TenantId, endpoint, agent, input, artifacts.ToArray(), ct));
    }
    static async Task<IResult> AgentCancellations(HttpContext c, ILiveResponseRepository r, CancellationToken ct) { if (!Agent(c, out var p, out var endpoint, out var agent) || Installation(c) is not { } installation) return Results.Unauthorized(); return Ok(c, await r.CancellationsAsync(p.TenantId, endpoint, agent, installation, ct)); }
}
